165	// The hook is typed against Error, so a rejection that is not one is wrapped with the original as its cause; the caller still gets it unchanged.
166	function asError(value: unknown): Error {
167	  if (value instanceof Error) return value;
168	  return new Error(readableRejection(value), {cause: value});
169	}
170	
171	// A string is its own message; anything else is serialized, with String() covering what JSON cannot, circular structures included.
172	function readableRejection(value: unknown): string {
173	  if (typeof value === 'string') return value;
174	  try {
175	    return JSON.stringify(value) ?? String(value);
176	  } catch {
177	    return String(value);
178	  }
179	}
180	
181	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
182	function normalizeToolRounds(value: number | undefined): number {
183	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
184	  return Math.max(0, Math.floor(value));
185	}
186	
187	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
188	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
189	  if (round < maxToolRounds) return false;
190	  log.warn('orchestrator', 'tool budget exhausted', {
191	    maxToolRounds,
192	    requestedTools: pendingToolCalls.map(tc => tc.name),
193	  });
194	  return true;
195	}
196	
197	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
198	async function* closeExhaustedTurn(
199	  session: ChatSession,
200	  budget: ToolBudgetInfo,
201	  hook?: OnToolBudgetExhausted
202	): AsyncGenerator<MessageChunk, string> {
203	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
204	  if (sentence !== '') yield {type: 'text', text: sentence};
205	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
206	  return sentence;
207	}
208	
209	interface RoundOutcome {
210	  stopReason: string;
211	  text: string;
212	  usage?: UsageMetadata;
213	}
214	
215	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
216	async function* streamRound(
217	  provider: AIProvider,
218	  request: SendMessageParams,
219	  pendingToolCalls: ToolCall[]
220	): AsyncGenerator<MessageChunk, RoundOutcome> {
221	  let stopReason = '';
222	  let text = '';
223	  let usage: UsageMetadata | undefined;
224	
225	  for await (const chunk of provider.sendMessage(request)) {
226	    yield chunk;
227	    collectToolCalls(chunk, pendingToolCalls);
228	    stopReason = extractStopReason(chunk) ?? stopReason;
229	    usage = extractUsage(chunk) ?? usage;
230	    if (chunk.type === 'text') text += chunk.text;
231	  }
232	
233	  return {stopReason, text, usage};
234	}
235	
236	// A changed message is also written back to the session's last user entry.
237	async function rewriteUserMessage(
238	  session: ChatSession,
239	  userMessage: string,
240	  hook: (session: ChatSession, userMessage: string) => Promise<string>
241	): Promise<string> {
242	  const modified = await hook(session, userMessage);
243	  if (modified === userMessage) return userMessage;
244	
245	  updateLastUserContent(session, modified);
246	  return modified;
247	}
248	
249	function lastUserContent(session: ChatSession): string {
250	  for (let i = session.entries.length - 1; i >= 0; i--) {
251	    const entry = session.entries[i];
252	    if (entry.role === 'user') return entry.content;
253	  }
254	  return '';
255	}
256	
257	function updateLastUserContent(session: ChatSession, content: string): void {
258	  for (let i = session.entries.length - 1; i >= 0; i--) {
259	    const entry = session.entries[i];
260	    if (entry.role === 'user') {
261	      entry.content = content;
262	      return;
263	    }
264	  }
265	}
266	
267	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
268	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
269	  const context: ToolContext = {
270	    userId: session.userId,
271	    sessionId: session.sessionId,
272	    workspaceId: session.workspaceId,
273	    authHeaders: session.authHeaders,
274	  };
275	
276	  return async (tc: ToolCall): Promise<ToolResponse> => {
277	    const declined =
278	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
279	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
280	  };
281	}
282	
283	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
284	async function consultPolicy(
285	  policy: BeforeToolCall,
286	  session: ChatSession,
287	  tc: ToolCall
288	): Promise<ToolResponse | undefined> {
289	  try {
290	    return await policy(session, tc);
291	  } catch (error) {
292	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
293	      tool: tc.name,
294	      errorType: error instanceof Error ? error.name : typeof error,
295	    });
296	    return {result: `The ${tc.name} call was declined and not performed.`};
297	  }
298	}
299	
300	async function executeToolCalls(
301	  pendingToolCalls: ToolCall[],
302	  messages: Message[],
303	  session: ChatSession,
304	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
305	): Promise<ToolExecutionResult> {
306	  messages.push(buildToolCallMessages(pendingToolCalls));
307	
308	  const responses = await Promise.all(
309	    pendingToolCalls.map(async tc => {
310	      const response = await runToolCall(tc);
311	      return {tc, response};
312	    })
313	  );
314	
315	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
316	    type: 'tool_result' as const,
317	    toolUseId: tc.id,
318	    content: response.result,
319	  }));
320	  messages.push({role: 'user', content: toolResults});
321	
322	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
323	
324	  return {
325	    clientMessages: assignEntryIndices(rawClientMessages, session),
326	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
327	  };
328	}
329	
330	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
331	  return clientMessages.map(msg => {
332	    if (msg.type !== 'entry_upsert') return msg;
333	    const index = appendEntry(session, msg.entry);
334	    return {...msg, index};
335	  });
336	}
337	
338	// Adds per-round token counts so the hook receives the total across all provider calls in the turn.
339	function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
340	  if (!acc) return next;
341	  if (!next) return acc;
342	  return {
343	    inputTokens: acc.inputTokens + next.inputTokens,
344	    outputTokens: acc.outputTokens + next.outputTokens,
345	    totalTokens: acc.totalTokens + next.totalTokens,
346	  };
347	}
348	
349	// A store outage is not a reason to fail the turn the customer already received.
350	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
351	  if (!store?.save) return;
352	
353	  try {
354	    await store.save(session);
355	  } catch (error) {
356	    const message = error instanceof Error ? error.message : String(error);
357	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
358	  }
359	}
