1	/**
2	 * no-nondeterministic-tests — a test must produce the same result on every
3	 * run. A clock read or a random draw inside a test file makes its outcome
4	 * depend on when and where it ran, which is how "flaky" gets into the
5	 * vocabulary.
6	 *
7	 * Active only in test files (`*.test.*` / `*.spec.*`). What counts:
8	 *   - `Math.random()`                        — tamed by `vi.spyOn(Math, "random")` / `jest.spyOn(Math, "random")`
9	 *   - `Date.now()`, `new Date()` (no args),
10	 *     `performance.now()`                    — tamed by `vi|jest.useFakeTimers()` / `vi|jest.setSystemTime()`
11	 *   - `crypto.randomUUID()`                  — tamed by `vi|jest.mock("crypto")` / `("node:crypto")`
12	 * A taming call anywhere in the file (any `beforeEach`, any test) exempts
13	 * its whole category: the visitor collects offenders and taming markers in
14	 * one pass and decides at `Program:exit`, so order within the file does not
15	 * matter. `new Date("2026-01-01")` is a fixed value and is never reported.
16	 *
17	 * Detect-only: the fix is to inject the clock/random source or fake it.
18	 */
19	const TEST_FILE = /\.(test|spec)\.[cm]?[jt]sx?$/;
20	const TEST_FRAMEWORKS = new Set(["vi", "jest"]);
21	const CRYPTO_MODULE = /^(node:)?crypto$/;
22	const OFFENDER_CATEGORY = {
23	    "Math.random": "random",
24	    "Date.now": "time",
25	    "performance.now": "time",
26	    "crypto.randomUUID": "uuid",
27	};
28	function isIdentifierPair(callee) {
29	    return (callee.object.type === "Identifier" && callee.property.type === "Identifier");
30	}
31	function memberCallName(node) {
32	    const { callee } = node;
33	    const isPlainMember = callee.type === "MemberExpression" && !callee.computed;
34	    if (!isPlainMember || !isIdentifierPair(callee)) {
35	        return null;
36	    }
37	    return { object: callee.object.name, method: callee.property.name };
38	}
39	function isMathRandomSpy(node) {
40	    const [target, method] = node.arguments;
41	    return (target?.type === "Identifier" &&
42	        target.name === "Math" &&
43	        method?.type === "Literal" &&
44	        method.value === "random");
45	}
46	function isCryptoMock(node) {
47	    const [moduleName] = node.arguments;
48	    return (moduleName?.type === "Literal" &&
49	        CRYPTO_MODULE.test(String(moduleName.value)));
50	}
51	const TAMERS = {
52	    useFakeTimers: () => "time",
53	    setSystemTime: () => "time",
54	    spyOn: (node) => (isMathRandomSpy(node) ? "random" : null),
55	    mock: (node) => (isCryptoMock(node) ? "uuid" : null),
